package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	_ "github.com/shopspring/decimal"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsLabel string = strings.Repeat(" ", 20)
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var partRec PartRec
var partFileLines []string
var partFileIndex int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatPic(val int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	v := val % mod
	if v < 0 {
		v += mod
	}
	s := strconv.FormatInt(v, 10)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

// READ-PARA
func readPara() {
	if partFileIndex >= len(partFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := partFileLines[partFileIndex]
	partFileIndex++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	partRec.LbPart = line[0:8]
	partRec.LbRegion = line[8:11]
	serialStr := line[11:15]
	trimmed := strings.TrimSpace(serialStr)
	if trimmed == "" {
		partRec.LbSerial = 0
	} else {
		if v, err := strconv.ParseInt(trimmed, 10, 64); err == nil {
			partRec.LbSerial = v
		} else {
			partRec.LbSerial = 0
		}
	}
}

// PROCESS-PARA
func processPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	WsACount = int64(strings.Count(partRec.LbPart, "A"))

	// STRING ...
	target := []byte(strings.Repeat(" ", 20))
	ptr := 0
	delimBySpace := func(s string) string {
		idx := strings.Index(s, " ")
		if idx != -1 {
			return s[:idx]
		}
		return s
	}
	senderRegionEff := delimBySpace(partRec.LbRegion)
	senderPartEff := delimBySpace(partRec.LbPart)
	serialVal := partRec.LbSerial % 10000
	if serialVal < 0 {
		serialVal += 10000
	}
	serialFmt := fmt.Sprintf("%04d", serialVal)

	senders := []string{senderRegionEff, "-", senderPartEff, "-", serialFmt}
	for _, s := range senders {
		for i := 0; i < len(s); i++ {
			if ptr >= 20 {
				break
			}
			target[ptr] = s[i]
			ptr++
		}
		if ptr >= 20 {
			break
		}
	}
	WsLabel = string(target)
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA += WsACount
	WsTotalA %= 1000
	// ADD 1 TO WS-COUNT
	WsCount += 1
	WsCount %= 1000
	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	acStr := formatPic(WsACount, 2)
	fmt.Printf("%s A=%s\n", WsLabel, acStr)
	// PERFORM READ-PARA
	readPara()
}

// SUMMARY-PARA
func summaryPara() {
	countStr := formatPic(WsCount, 3)
	totalStr := formatPic(WsTotalA, 3)
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", countStr, totalStr)
}

// MAIN-PARA
func mainPara() {
	// OPEN INPUT PART-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			partFileLines = []string{}
		} else {
			fmt.Fprintf(os.Stderr, "open error: %v\n", err)
			os.Exit(1)
		}
	} else {
		defer f.Close()
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			partFileLines = append(partFileLines, line)
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
	}
	WsEofFlag = "N"
	partFileIndex = 0
	readPara()
	for !isInputDone() {
		processPara()
	}
	// CLOSE PART-FILE handled by defer
	summaryPara()
}

func main() {
	mainPara()
}
